fn map_entry_set_key_value_contains_projection(
    lowered_map: RustExpr,
    key: RustExpr,
    value: RustExpr,
    prefix: &str,
) -> RustExpr {
    let map_name = format!("{prefix}_map");
    let key_name = format!("{prefix}_key");
    let value_name = format!("{prefix}_value");
    RustExpr::Block {
        stmts: vec![
            RustStmt::Let {
                mutable: false,
                name: map_name.clone(),
                ty: None,
                value: Some(RustExpr::Unary {
                    op: "&".to_string(),
                    expr: Box::new(lowered_map),
                }),
            },
            RustStmt::Let {
                mutable: false,
                name: key_name.clone(),
                ty: None,
                value: Some(key),
            },
            RustStmt::Let {
                mutable: false,
                name: value_name.clone(),
                ty: None,
                value: Some(value),
            },
        ],
        tail: Some(Box::new(map_entry_set_key_value_contains_tail(
            RustExpr::Var(map_name),
            &key_name,
            &value_name,
        ))),
    }
}

fn map_entry_set_key_value_contains_tail(
    map: RustExpr,
    key_name: &str,
    value_name: &str,
) -> RustExpr {
    map_entry_key_value_contains_expr(
        map,
        RustExpr::Unary {
            op: "&".to_string(),
            expr: Box::new(RustExpr::Var(key_name.to_string())),
        },
        RustExpr::Unary {
            op: "&".to_string(),
            expr: Box::new(RustExpr::Var(value_name.to_string())),
        },
    )
}

fn map_entry_key_value_contains_expr(map: RustExpr, key: RustExpr, value: RustExpr) -> RustExpr {
    receiver_method_call_projection_exact(
        receiver_method_call_projection_exact(map, "get", vec![key]),
        "is_some_and",
        vec![RustExpr::Closure {
            is_move: false,
            return_type: None,
            params: vec![RustClosureParam {
                pattern: "value".to_string(),
                ty: None,
            }],
            body: RustClosureBody::Expr(Box::new(RustExpr::Binary {
                op: "==".to_string(),
                left: Box::new(RustExpr::Var("value".to_string())),
                right: Box::new(value),
            })),
        }],
    )
}

fn map_entry_tuple_matches_key_value_projection(
    entry: RustExpr,
    key: RustExpr,
    value: RustExpr,
) -> RustExpr {
    RustExpr::Binary {
        op: "&&".to_string(),
        left: Box::new(RustExpr::Binary {
            op: "==".to_string(),
            left: Box::new(key),
            right: Box::new(RustExpr::Unary {
                op: "&".to_string(),
                expr: Box::new(tuple_field_projection(entry.clone(), 0)),
            }),
        }),
        right: Box::new(RustExpr::Binary {
            op: "==".to_string(),
            left: Box::new(value),
            right: Box::new(RustExpr::Unary {
                op: "&".to_string(),
                expr: Box::new(tuple_field_projection(entry, 1)),
            }),
        }),
    }
}

fn lower_simple_map_entry_display_for_slot(
    expr: &Expr,
    env: &ShapeEnv,
    slot: &Slot,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    if !matches!(slot, Slot::StringConcatSegment | Slot::DisplaySegment) {
        return None;
    }
    if let Some(map_receiver) = map_entry_next_backing_receiver(Some(expr)) {
        let (_key_ty, _value_ty, receiver_is_optional_map) =
            map_type_args_from_expr_shape(map_receiver, env, ctx).unwrap_or_else(|| {
                (
                    JavaType::Unknown("map_entry_key".to_string()),
                    JavaType::Unknown("map_entry_value".to_string()),
                    false,
                )
            });
        let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
        let entry = iterator_next_projection_for_ctx(
            sequence_iteration_source_projection(
                lowered_map,
                receiver_is_optional_map,
                SequenceIterationProjection::Borrowed,
            ),
            ctx,
        );
        let entry_name = "__java_map_entry_display_entry";
        return Some(RustExpr::Block {
            stmts: vec![RustStmt::Let {
                mutable: false,
                name: entry_name.to_string(),
                ty: None,
                value: Some(entry),
            }],
            tail: Some(Box::new(macro_call_projection(
                "format",
                vec![
                    rust_string_literal_projection("{}={}"),
                    tuple_field_projection(RustExpr::Var(entry_name.to_string()), 0),
                    tuple_field_projection(RustExpr::Var(entry_name.to_string()), 1),
                ],
            ))),
        });
    }
    if let Some((key, value)) = map_entry_key_value_args(expr, env) {
        return Some(macro_call_projection(
            "format",
            vec![
                rust_string_literal_projection("{}={}"),
                lower_expr_for_slot_with_refinements(
                    &key,
                    env,
                    Slot::DisplaySegment,
                    ctx,
                    refinements,
                ),
                lower_expr_for_slot_with_refinements(
                    &value,
                    env,
                    Slot::DisplaySegment,
                    ctx,
                    refinements,
                ),
            ],
        ));
    }
    if !expr_is_stable_map_entry_projection(expr)
        && let Some((key_ty, value_ty)) = map_entry_type_args_from_expr_shape(expr, env, ctx)
    {
        let entry_name = "__java_map_entry_display_entry";
        let lowered = lower_expr_with_refinements(expr, env, ctx, refinements);
        return Some(RustExpr::Block {
            stmts: vec![RustStmt::Let {
                mutable: false,
                name: entry_name.to_string(),
                ty: None,
                value: Some(lowered),
            }],
            tail: Some(Box::new(macro_call_projection(
                "format",
                vec![
                    rust_string_literal_projection("{}={}"),
                    map_entry_field_display_projection(
                        RustExpr::Var(entry_name.to_string()),
                        0,
                        &key_ty,
                    ),
                    map_entry_field_display_projection(
                        RustExpr::Var(entry_name.to_string()),
                        1,
                        &value_ty,
                    ),
                ],
            ))),
        });
    }
    let (key_ty, value_ty) = map_entry_type_args_from_expr_shape(expr, env, ctx)?;
    let lowered = lower_expr_with_refinements(expr, env, ctx, refinements);
    Some(macro_call_projection(
        "format",
        vec![
            rust_string_literal_projection("{}={}"),
            map_entry_field_display_projection(lowered.clone(), 0, &key_ty),
            map_entry_field_display_projection(lowered, 1, &value_ty),
        ],
    ))
}

fn map_entry_field_display_projection(
    entry: RustExpr,
    field_index: usize,
    field_ty: &JavaType,
) -> RustExpr {
    let field = tuple_field_projection(entry, field_index);
    if matches!(field_ty, JavaType::Wildcard(_) | JavaType::Unknown(_))
        || java_type_is_erased_object_name(field_ty)
    {
        apply_java_display_plan(field, JavaDisplayPlan::ErasedObject)
    } else {
        apply_java_display_plan(apply_clone_projection(field), JavaDisplayPlan::ConcatValue)
    }
}

fn lower_simple_map_entry_new_for_slot(
    expr: &Expr,
    env: &ShapeEnv,
    slot: &Slot,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    let target_shape = slot_target_shape(slot)?;
    let Expr::New { ty, args, .. } = expr else {
        return None;
    };
    if !java_type_is_simple_map_entry(ty) || args.len() != 2 {
        return None;
    }
    let (key_ty, value_ty) = if shape_is_erased_object_boundary(target_shape) {
        simple_map_entry_type_args_from_java_type(ty)?
    } else {
        map_entry_type_args_from_java_type(&target_shape.java_ty)?
    };
    let actual = value_shape_for_java_type(
        ctx.representations,
        JavaType::Named {
            name: "java.util.Map.Entry".to_string(),
            args: vec![key_ty.clone(), value_ty.clone()],
        },
    );
    let key_shape = value_shape_for_java_type(ctx.representations, key_ty.clone());
    let value_shape = value_shape_for_java_type(ctx.representations, value_ty.clone());
    let lower_component = |arg: &Expr, ty: &JavaType, shape: RustSlotShape| {
        if shape_is_erased_object_boundary(target_shape)
            && matches!(arg, Expr::Literal(Literal::Null))
        {
            let rust_ty = emit::emit_type(&rust_type_for_java_type_with_facts(ty, ctx.facts));
            typed_none_projection(&rust_ty)
        } else {
            lower_expr_for_slot_with_refinements(arg, env, argument_slot(shape), ctx, refinements)
        }
    };
    let tuple = RustExpr::Tuple(vec![
        lower_component(&args[0], &key_ty, key_shape),
        lower_component(&args[1], &value_ty, value_shape),
    ]);
    Some(apply_expr_to_slot_via_plan(tuple, actual, slot, ctx.facts))
}

fn simple_map_entry_type_args_from_java_type(ty: &JavaType) -> Option<(JavaType, JavaType)> {
    let JavaType::Named { args, .. } = ty else {
        return None;
    };
    Some((args.first()?.clone(), args.get(1)?.clone()))
}

fn simple_map_entry_constructor_args(expr: &Expr) -> Option<(&Expr, &Expr)> {
    let Expr::New { ty, args, .. } = expr else {
        return None;
    };
    if !java_type_is_simple_map_entry(ty) || args.len() != 2 {
        return None;
    }
    Some((&args[0], &args[1]))
}

fn map_entry_key_value_args(expr: &Expr, env: &ShapeEnv) -> Option<(Expr, Expr)> {
    if let Some((key, value)) = simple_map_entry_constructor_args(expr) {
        return Some((key.clone(), value.clone()));
    }
    let Expr::Var(name) = expr else {
        return None;
    };
    env.simple_map_entry_value(name)
        .map(|(key, value)| (key.clone(), value.clone()))
}

fn map_entry_key_value_projection_args(
    expr: &Expr,
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<(RustExpr, RustExpr)> {
    if !expr_is_stable_map_entry_projection(expr) {
        return None;
    }
    map_entry_type_args_from_expr_shape(expr, env, ctx)?;
    let lowered = lower_expr_with_refinements(expr, env, ctx, refinements);
    Some((
        apply_clone_projection(tuple_field_projection(lowered.clone(), 0)),
        apply_clone_projection(tuple_field_projection(lowered, 1)),
    ))
}

fn expr_is_stable_map_entry_projection(expr: &Expr) -> bool {
    match expr {
        Expr::Var(_) | Expr::This | Expr::Super => true,
        Expr::FieldAccess(receiver, _) => expr_is_stable_map_entry_projection(receiver),
        Expr::ArrayAccess(array, index) => {
            expr_is_stable_map_entry_projection(array) && expr_is_stable_map_entry_projection(index)
        }
        _ => false,
    }
}

fn java_type_is_simple_map_entry(ty: &JavaType) -> bool {
    let JavaType::Named { name, .. } = ty else {
        return false;
    };
    matches!(
        name.rsplit('.').next().unwrap_or(name).trim(),
        "SimpleEntry" | "SimpleImmutableEntry"
    )
}

fn simple_map_entry_constructor_is_immutable(expr: &Expr) -> bool {
    let Expr::New { ty, args, .. } = expr else {
        return false;
    };
    args.len() == 2 && java_type_is_simple_immutable_map_entry(ty)
}

fn java_type_is_simple_immutable_map_entry(ty: &JavaType) -> bool {
    let JavaType::Named { name, .. } = ty else {
        return false;
    };
    name.rsplit('.').next().unwrap_or(name).trim() == "SimpleImmutableEntry"
}

fn map_entry_set_backing_receiver<'a>(
    receiver: Option<&'a Expr>,
    env: &'a ShapeEnv,
) -> Option<&'a Expr> {
    if let Some(Expr::Var(local_name)) = receiver
        && let Some(map_receiver) = env.map_entry_set_view_receiver(local_name)
    {
        return Some(map_receiver);
    }
    let Expr::Call {
        receiver: Some(map_receiver),
        name: entry_set_name,
        args: entry_set_args,
        ..
    } = receiver?
    else {
        return None;
    };
    if !entry_set_args.is_empty() || !matches!(entry_set_name.as_str(), "entrySet" | "entry_set") {
        return None;
    }
    Some(map_receiver)
}

fn lower_map_values_remove_call(
    receiver: Option<&Expr>,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    let map_receiver = map_values_backing_receiver(receiver, env)?;
    lower_map_values_call_from_backing_map(map_receiver, name, args, env, ctx, refinements)
}

fn map_values_backing_receiver<'a>(
    receiver: Option<&'a Expr>,
    env: &'a ShapeEnv,
) -> Option<&'a Expr> {
    if let Some(Expr::Var(local_name)) = receiver
        && let Some(map_receiver) = env.map_values_view_receiver(local_name)
    {
        return Some(map_receiver);
    }
    let Expr::Call {
        receiver: Some(map_receiver),
        name: values_name,
        args: values_args,
        ..
    } = receiver?
    else {
        return None;
    };
    if !values_args.is_empty() || values_name != "values" {
        return None;
    }
    Some(map_receiver)
}

fn lower_map_values_call_from_backing_map(
    map_receiver: &Expr,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    match (name, args.len()) {
        ("remove", 1) => {
            lower_map_values_remove_from_backing_map(map_receiver, args, env, ctx, refinements)
        }
        ("removeAll" | "remove_all", 1) => {
            lower_map_values_remove_all_from_backing_map(map_receiver, args, env, ctx, refinements)
        }
        ("containsAll" | "contains_all", 1) => lower_map_values_contains_all_from_backing_map(
            map_receiver,
            args,
            env,
            ctx,
            refinements,
        ),
        ("retainAll" | "retain_all", 1) => {
            lower_map_values_retain_all_from_backing_map(map_receiver, args, env, ctx, refinements)
        }
        ("add", 1) | ("addAll" | "add_all", 1) => {
            lower_map_values_unsupported_mutation_from_backing_map(
                map_receiver,
                args,
                env,
                ctx,
                refinements,
            )
        }
        ("clear", 0) => {
            lower_map_key_set_clear_from_backing_map(map_receiver, env, ctx, refinements)
        }
        ("size", 0) => {
            let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
            Some(len_i32_projection(lowered_map))
        }
        ("isEmpty" | "is_empty", 0) => {
            let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
            Some(receiver_method_call_projection_exact(
                lowered_map,
                "is_empty",
                Vec::new(),
            ))
        }
        ("contains", 1) => lower_map_values_contains_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        _ => None,
    }
}

fn lower_map_values_unsupported_mutation_from_backing_map(
    map_receiver: &Expr,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    let receiver_ty = crate::types::infer_expr_type(map_receiver, env.type_env());
    if !crate::stdlib::java_collection_kind_for_type(&receiver_ty)
        .is_some_and(|kind| kind.is_map_like())
    {
        return None;
    }

    let lowered_map = lower_expr_with_refinements(map_receiver, env, ctx, refinements);
    let mut stmts = vec![RustStmt::Let {
        mutable: expr_is_shared_native_map(map_receiver, env),
        name: "__java_map_values_unsupported_map".to_string(),
        ty: None,
        value: Some(mutable_map_view_backing_borrow(
            map_receiver,
            lowered_map,
            env,
        )),
    }];
    for (index, arg) in args.iter().enumerate() {
        stmts.push(RustStmt::Let {
            mutable: false,
            name: format!("__java_map_values_unsupported_arg{index}"),
            ty: None,
            value: Some(lower_expr_with_refinements(arg, env, ctx, refinements)),
        });
    }
    Some(RustExpr::Block {
        stmts,
        tail: Some(Box::new(unsupported_operation_exception_result_expr(
            ctx,
            "Java Map.values view does not support add",
        ))),
    })
}

fn unsupported_operation_exception_result_expr(ctx: LowerCtx, message: &str) -> RustExpr {
    let result = function_call_projection(
        RustExpr::path(["Err"]),
        vec![crate::exception_lowering::new_exception_expr(
            "UnsupportedOperationException",
            rust_string_literal_projection(message),
        )],
    );
    if ctx.result_propagation_mode == ResultPropagationMode::Propagate {
        propagate_result_projection(result)
    } else {
        unwrap_result_or_panic_uncaught_java_exception(result)
    }
}

