    #[test]
    fn make_java_null_expect_catchable_recurses_inside_try_expression() {
        let expr = RustExpr::Try(Box::new(RustExpr::Call {
            function: Box::new(RustExpr::Var("consume".to_string())),
            args: vec![java_null_receiver_expect_expr("value")],
        }));

        let rewritten = make_java_null_expect_catchable(expr);
        let rendered = emit_expr(&rewritten);

        assert!(rendered.contains("consume("));
        assert!(rendered.contains("value.ok_or_else"));
        assert!(rendered.contains("NullPointerException"));
        assert!(rendered.ends_with('?'));
        assert!(!rendered.contains(".expect(\"Java null receiver\")"));
    }

    #[test]
    fn make_java_null_expect_catchable_recovers_parseable_raw_expression() {
        let expr = RustExpr::Raw("helper(value.expect(\"Java null receiver\"))".to_string());

        let rewritten = make_java_null_expect_catchable(expr);
        let rendered = emit_expr(&rewritten);

        assert!(rendered.contains("helper("));
        assert!(rendered.contains("value.ok_or_else"));
        assert!(rendered.contains("NullPointerException"));
        assert!(rendered.contains('?'));
        assert!(!rendered.contains(".expect(\"Java null receiver\")"));
        assert!(!rewritten.is_raw_leaf());

        let opaque = RustExpr::Raw("helper(value.expect(\"Java null receiver\"".to_string());
        let opaque_rewritten = make_java_null_expect_catchable(opaque.clone());
        assert_eq!(opaque_rewritten, opaque);
    }

    #[test]
    fn make_java_null_expect_catchable_collapses_direct_try_null_expect() {
        let expr = RustExpr::Try(Box::new(java_null_receiver_expect_expr("value")));

        let rewritten = make_java_null_expect_catchable(expr);
        let rendered = emit_expr(&rewritten);

        assert_eq!(
            rendered.matches('?').count(),
            1,
            "direct null-expect propagation should not become a double try: {rendered}"
        );
        assert!(rendered.contains("value.ok_or_else"));
        assert!(rendered.contains("NullPointerException"));
        assert!(!rendered.contains(".expect(\"Java null receiver\")"));
    }

    #[test]
    fn fallible_array_index_read_reports_java_index_and_length() {
        let expr = fallible_array_index_read_expr(
            RustExpr::Var("values".to_string()),
            RustExpr::Cast {
                expr: Box::new(RustExpr::Var("index".to_string())),
                ty: "usize".to_string(),
            },
            &JavaType::Primitive(PrimitiveType::Int),
        );

        let rendered = emit_expr(&expr);

        assert!(rendered.contains("let __java_arrays_source = &values"));
        assert!(rendered.contains("let __java_arrays_index = index"));
        assert!(rendered.contains(
            "__java_arrays_source.get(__java_arrays_index as usize).copied().ok_or_else"
        ));
        assert!(rendered.contains(
            "format!(\"Index {} out of bounds for length {}\", __java_arrays_index, __java_arrays_source.len())"
        ));
        assert!(!rendered.contains("Java index out of bounds"));
        assert!(!rendered.starts_with("*{"));
    }

    #[test]
    fn fallible_primitive_array_index_copies_before_inline_source_expires() {
        let expr = fallible_owned_array_index_read_expr(
            RustExpr::VecLiteral(vec![
                RustExpr::Literal("6".to_string()),
                RustExpr::Literal("7".to_string()),
            ]),
            RustExpr::Literal("1".to_string()),
            &JavaType::Primitive(PrimitiveType::Int),
        );

        let rendered = emit_expr(&expr);

        assert!(rendered.contains("let __java_arrays_source = vec![6, 7]"));
        assert!(rendered.contains("let __java_arrays_len = __java_arrays_source.len()"));
        assert!(rendered.contains(
            "__java_arrays_source.into_iter().nth(__java_arrays_index as usize).ok_or_else"
        ));
        assert!(!rendered.starts_with("*{"));
    }

    #[test]
    fn fallible_array_index_write_reports_java_index_and_length() {
        let expr = fallible_array_index_write_expr(
            RustExpr::Var("values".to_string()),
            RustExpr::Cast {
                expr: Box::new(RustExpr::Var("index".to_string())),
                ty: "usize".to_string(),
            },
            RustExpr::Literal("9".to_string()),
        );

        let rendered = emit_expr(&expr);

        assert!(rendered.contains("let __java_arrays_target = &mut values"));
        assert!(rendered.contains("let __java_arrays_index = index"));
        assert!(
            rendered
                .contains("__java_arrays_target.get_mut(__java_arrays_index as usize).ok_or_else")
        );
        assert!(rendered.contains("let __java_arrays_len = __java_arrays_target.len()"));
        assert!(rendered.contains(
            "format!(\"Index {} out of bounds for length {}\", __java_arrays_index, __java_arrays_len)"
        ));
        assert!(rendered.contains("let __java_assignment_value = 9"));
        assert!(rendered.contains("*__java_arrays_slot = __java_assignment_value"));
        assert!(
            rendered.find("let __java_assignment_value").unwrap()
                < rendered.find("let __java_arrays_target").unwrap()
        );
        assert!(!rendered.contains("values[index as usize] = 9"));
    }

    #[test]
    fn fallible_array_index_compound_write_reads_checked_slot_before_assigning() {
        let expr = fallible_array_index_write_expr_with_slot_stmts(
            RustExpr::Var("values".to_string()),
            RustExpr::Var("index".to_string()),
            vec![ordered_assignment_let_stmt(
                ORDERED_ASSIGNMENT_OLD_TEMP,
                deref_borrowed_projection(RustExpr::Var("__java_arrays_slot".to_string())),
            )],
            RustExpr::Binary {
                op: "+".to_string(),
                left: Box::new(ordered_assignment_old_temp_expr()),
                right: Box::new(RustExpr::Literal("1".to_string())),
            },
        );

        let rendered = emit_expr(&expr);

        assert!(
            rendered
                .contains("__java_arrays_target.get_mut(__java_arrays_index as usize).ok_or_else")
        );
        assert!(rendered.contains("let __java_assignment_old = *__java_arrays_slot"));
        assert!(rendered.contains("*__java_arrays_slot = __java_assignment_old + 1"));
        assert!(
            rendered.find("let __java_arrays_slot").unwrap()
                < rendered.find("let __java_assignment_old").unwrap()
        );
    }

