    #[test]
    fn direct_optional_clone_recovery_unwrap_uses_structured_projection() {
        let direct = RustExpr::MethodCall {
            receiver: Box::new(RustExpr::Var("value".to_string())),
            method: "unwrap".to_string(),
            args: Vec::new(),
        };
        let recovered =
            direct_optional_clone_recovery_unwrap_expr(&direct, "value", false).unwrap();
        assert_eq!(
            emit_expr(&recovered),
            "value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\")"
        );
        assert_eq!(
            recovered.recorded_shape(),
            Some(RustExprShape::OwnedRecovery)
        );
        assert!(!recovered.is_raw_leaf());

        let cloned = RustExpr::MethodCall {
            receiver: Box::new(RustExpr::MethodCall {
                receiver: Box::new(RustExpr::Var("value".to_string())),
                method: "clone".to_string(),
                args: Vec::new(),
            }),
            method: "unwrap".to_string(),
            args: Vec::new(),
        };
        let erased = direct_optional_clone_recovery_unwrap_expr(&cloned, "value", true).unwrap();
        let erased_expected = [
            "value.as_ref().map(|value| ",
            "java_clone_erased_object_ref",
            "(value))/* TODO(translation): validate added clone */.expect(\"Java null receiver\")",
        ]
        .concat();
        assert_eq!(emit_expr(&erased), erased_expected);
        assert_eq!(erased.recorded_shape(), Some(RustExprShape::OwnedRecovery));

        let nested_call = RustExpr::Call {
            function: Box::new(RustExpr::Var("helper".to_string())),
            args: vec![direct],
        };
        let nested_recovered =
            direct_optional_clone_recovery_unwrap_expr(&nested_call, "value", false).unwrap();
        assert_eq!(
            emit_expr(&nested_recovered),
            "helper(value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\"))"
        );
        assert!(matches!(
            nested_recovered,
            RustExpr::Call { args, .. }
                if matches!(args.as_slice(), [RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. }])
        ));
        let struct_lit = RustExpr::StructLit {
            name: "Holder".to_string(),
            fields: vec![(
                "item".to_string(),
                RustExpr::MethodCall {
                    receiver: Box::new(RustExpr::Var("value".to_string())),
                    method: "unwrap".to_string(),
                    args: Vec::new(),
                },
            )],
        };
        let struct_recovered =
            direct_optional_clone_recovery_unwrap_expr(&struct_lit, "value", false).unwrap();
        assert_eq!(
            emit_expr(&struct_recovered),
            "Holder { item: value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\") }"
        );
        assert!(matches!(
            struct_recovered,
            RustExpr::StructLit { fields, .. }
                if matches!(
                    fields.as_slice(),
                    [(field, RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. })]
                        if field == "item"
                )
        ));

        let raw_literal_like = RustExpr::Raw("\"value.unwrap()\".to_string()".to_string());
        assert!(
            direct_optional_clone_recovery_unwrap_expr(&raw_literal_like, "value", false).is_none()
        );

        let raw_unwrap = RustExpr::Raw("value.unwrap()".to_string());
        let raw_recovered =
            direct_optional_clone_recovery_unwrap_expr(&raw_unwrap, "value", false).unwrap();
        assert_eq!(
            emit_expr(&raw_recovered),
            "value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\")"
        );
        assert!(!raw_recovered.is_raw_leaf());

        let raw_binary_unwrap = RustExpr::Raw("1 + value.unwrap()".to_string());
        let raw_binary_recovered =
            direct_optional_clone_recovery_unwrap_expr(&raw_binary_unwrap, "value", false).unwrap();
        assert_eq!(
            emit_expr(&raw_binary_recovered),
            "1 + value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\")"
        );
        assert!(matches!(
            raw_binary_recovered,
            RustExpr::Binary { right, .. }
                if matches!(right.as_ref(), RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. })
        ));

        let nested = RustExpr::MethodCall {
            receiver: Box::new(RustExpr::Field(
                Box::new(RustExpr::Var("owner".to_string())),
                "value".to_string(),
            )),
            method: "unwrap".to_string(),
            args: Vec::new(),
        };
        assert!(direct_optional_clone_recovery_unwrap_expr(&nested, "value", false).is_none());

        let binary = RustExpr::Binary {
            op: "+".to_string(),
            left: Box::new(RustExpr::Literal("1".to_string())),
            right: Box::new(RustExpr::MethodCall {
                receiver: Box::new(RustExpr::Var("value".to_string())),
                method: "unwrap".to_string(),
                args: Vec::new(),
            }),
        };
        let binary_recovered =
            direct_optional_clone_recovery_unwrap_expr(&binary, "value", false).unwrap();
        assert_eq!(
            emit_expr(&binary_recovered),
            "1 + value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\")"
        );
        assert!(matches!(
            binary_recovered,
            RustExpr::Binary { right, .. }
                if matches!(right.as_ref(), RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. })
        ));

        let conditional = RustExpr::If {
            condition: Box::new(RustExpr::Var("ready".to_string())),
            then_expr: Box::new(RustExpr::MethodCall {
                receiver: Box::new(RustExpr::Var("value".to_string())),
                method: "unwrap".to_string(),
                args: Vec::new(),
            }),
            else_expr: Box::new(RustExpr::Var("fallback".to_string())),
        };
        let conditional_recovered =
            direct_optional_clone_recovery_unwrap_expr(&conditional, "value", false).unwrap();
        assert!(matches!(
            conditional_recovered,
            RustExpr::If { then_expr, .. }
                if matches!(then_expr.as_ref(), RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. })
        ));

        let block = RustExpr::Block {
            stmts: vec![RustStmt::Let {
                mutable: false,
                name: "item".to_string(),
                ty: None,
                value: Some(RustExpr::MethodCall {
                    receiver: Box::new(RustExpr::Var("value".to_string())),
                    method: "unwrap".to_string(),
                    args: Vec::new(),
                }),
            }],
            tail: Some(Box::new(RustExpr::Var("item".to_string()))),
        };
        let block_recovered =
            direct_optional_clone_recovery_unwrap_expr(&block, "value", false).unwrap();
        assert!(matches!(
            block_recovered,
            RustExpr::Block { stmts, .. }
                if matches!(
                    stmts.as_slice(),
                    [RustStmt::Let { value: Some(RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. }), .. }]
                )
        ));
    }

    #[test]
    fn source_raw_expr_lowering_recovers_parseable_projection_before_raw_leaf() {
        let program = Box::leak(Box::new(Program::default()));
        let facts = Box::leak(Box::new(FactSet::default()));
        let external_index = Box::leak(Box::new(facts.external_lookup_index()));
        let usage = Box::leak(Box::new(crate::usage::UsageFacts::default()));
        let representations = Box::leak(Box::new(RepresentationPlan::default()));
        let signatures = Box::leak(Box::new(SignaturePlan::default()));
        let exceptions = Box::leak(Box::new(ProgramExceptionPlan::default()));
        let fallibility = Box::leak(Box::new(
            crate::exception_plan::ProgramFallibilityPlan::default(),
        ));
        let callable_analysis = Box::leak(Box::new(CallableAnalysis::new(
            usage,
            exceptions,
            fallibility,
        )));
        let liveness = Box::leak(Box::new(crate::liveness::LivenessAnalysis::default()));
        let env = ShapeEnv::default();
        let ctx = LowerCtx {
            program,
            facts,
            external_index,
            callable_analysis,
            representations,
            signatures,
            current_type: None,
            current_method: None,
            current_method_decl: None,
            current_constructor: None,
            current_receiver: None,
            current_self_handle: None,
            current_local_shapes: &[],
            current_return_shape: None,
            exceptions,
            control_flow_plans: &[],
            support_local_type_program: program,
            source_summary_type_program: program,
            context_sources_are_emitted: false,
            current_stmt: None,
            try_capture_preinitialized_names: None,
            liveness,
            result_propagation_mode: ResultPropagationMode::UncaughtPanic,
            lowering_inherited_method_body: false,
            inherited_method_declaring_type: None,
            constructor_return_signal_only: false,
        };

        let lowered = lower_expr(&Expr::Raw("helper(value.unwrap())".to_string()), &env, ctx);
        assert_eq!(emit_expr(&lowered), "helper(value.unwrap())");
        assert!(!lowered.is_raw_leaf());

        let malformed_call = lower_expr(&Expr::Raw("helper(self..broken)".to_string()), &env, ctx);
        assert_eq!(emit_expr(&malformed_call), "helper(self..broken)");
        assert!(
            matches!(malformed_call.unshaped(), RustExpr::Raw(raw) if raw == "helper(self..broken)"),
            "partially recovered raw expressions must not become structured calls with raw children: {malformed_call:?}"
        );

        let binary = lower_expr(
            &Expr::Raw("self.value == other.value".to_string()),
            &env,
            ctx,
        );
        assert_eq!(emit_expr(&binary), "self.value == other.value");
        assert!(!binary.is_raw_leaf());

        let opaque = lower_expr(&Expr::Raw("self..broken".to_string()), &env, ctx);
        assert_eq!(opaque, RustExpr::Raw("self..broken".to_string()));
    }

    #[test]
    fn optional_clone_recovery_recovers_parseable_raw_statements() {
        let raw_return = RustStmt::Raw("return value.unwrap();".to_string());
        assert!(rust_stmt_has_optional_unwrap_or_java_null_expect(
            &raw_return
        ));
        let recovered_return =
            recover_optional_clone_recovery_stmt(raw_return, "value", false).unwrap();
        let RustStmt::Return(Some(returned)) = recovered_return else {
            panic!("expected structured return from raw optional unwrap");
        };
        assert_eq!(
            emit_expr(&returned),
            "value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\")"
        );
        assert!(matches!(
            returned,
            RustExpr::Shaped {
                shape: RustExprShape::OwnedRecovery,
                ..
            }
        ));

        let raw_expr = RustStmt::Raw("helper(value.unwrap());".to_string());
        assert!(rust_stmt_has_optional_unwrap_or_java_null_expect(&raw_expr));
        let recovered_expr =
            recover_optional_clone_recovery_stmt(raw_expr, "value", false).unwrap();
        let RustStmt::Expr(expr) = recovered_expr else {
            panic!("expected structured expression statement from raw optional unwrap");
        };
        assert_eq!(
            emit_expr(&expr),
            "helper(value.as_ref().cloned()/* TODO(translation): validate added clone */.expect(\"Java null receiver\"))"
        );
        assert!(matches!(
            expr.unshaped(),
            RustExpr::Call { args, .. }
                if matches!(
                    args.as_slice(),
                    [RustExpr::Shaped { shape: RustExprShape::OwnedRecovery, .. }]
                )
        ));

        let literal = RustStmt::Raw("return \"value.unwrap()\";".to_string());
        assert!(!rust_stmt_has_optional_unwrap_or_java_null_expect(&literal));
        assert!(recover_optional_clone_recovery_stmt(literal, "value", false).is_none());
    }

    #[test]
    fn replace_self_receiver_recurses_through_shaped_exprs() {
        let actual = RustSlotShape::for_storage(JavaType::String);
        let expr = RustExpr::shaped_as(
            RustExprShape::StringView,
            Some(actual.clone()),
            RustExpr::Field(
                Box::new(RustExpr::Var("self".to_string())),
                "name".to_string(),
            ),
        );

        let replaced = replace_self_receiver(expr, "__java_self.clone()");

        assert_eq!(emit_expr(&replaced), "__java_self.name", "{replaced:?}");
        assert_eq!(replaced.recorded_shape(), Some(RustExprShape::StringView));
        assert_eq!(replaced.recorded_slot_shape(), Some(&actual));

        let marked = RustExpr::PostfixComment {
            expr: Box::new(RustExpr::Field(
                Box::new(RustExpr::Var("self".to_string())),
                "name".to_string(),
            )),
            comment: "/* marker */".to_string(),
        };
        let replaced = replace_self_receiver(marked, "__java_self.clone()");
        assert_eq!(emit_expr(&replaced), "__java_self.name/* marker */");

        assert_eq!(
            replace_self_receiver(RustExpr::Var("self".to_string()), "__java_self.clone()"),
            RustExpr::MethodCall {
                receiver: Box::new(RustExpr::Var("__java_self".to_string())),
                method: "clone".to_string(),
                args: Vec::new(),
            }
        );
        assert_eq!(
            replace_self_receiver(
                RustExpr::Var("self".to_string()),
                "__java_self.clone().unwrap()"
            ),
            RustExpr::MethodCall {
                receiver: Box::new(RustExpr::MethodCall {
                    receiver: Box::new(RustExpr::Var("__java_self".to_string())),
                    method: "clone".to_string(),
                    args: Vec::new(),
                }),
                method: "unwrap".to_string(),
                args: Vec::new(),
            }
        );
        assert_eq!(
            replace_self_receiver(RustExpr::Var("self".to_string()), "__java_self.inner"),
            RustExpr::Field(
                Box::new(RustExpr::Var("__java_self".to_string())),
                "inner".to_string(),
            )
        );
        assert_eq!(
            replace_self_receiver(
                RustExpr::Var("self".to_string()),
                "__java_self.inner.clone()"
            ),
            RustExpr::MethodCall {
                receiver: Box::new(RustExpr::Field(
                    Box::new(RustExpr::Var("__java_self".to_string())),
                    "inner".to_string(),
                )),
                method: "clone".to_string(),
                args: Vec::new(),
            }
        );
        assert_eq!(
            replace_self_receiver(
                RustExpr::Var("self".to_string()),
                "__java_self.inner.clone().unwrap()",
            ),
            RustExpr::MethodCall {
                receiver: Box::new(RustExpr::MethodCall {
                    receiver: Box::new(RustExpr::Field(
                        Box::new(RustExpr::Var("__java_self".to_string())),
                        "inner".to_string(),
                    )),
                    method: "clone".to_string(),
                    args: Vec::new(),
                }),
                method: "unwrap".to_string(),
                args: Vec::new(),
            }
        );
        assert_eq!(
            replace_self_receiver(RustExpr::Var("self".to_string()), "__java_self..inner"),
            RustExpr::Raw("__java_self..inner".to_string())
        );
    }

