    fn inner_constructor_target(name: &str) -> NewTargetPlan {
        NewTargetPlan::new(
            RustSlotShape::conservative(JavaType::Named {
                name: name.to_string(),
                args: Vec::new(),
            }),
            "new".to_string(),
            None,
            None,
            None,
        )
    }

    fn resolved_inner_constructor(name: &str) -> ResolvedConstructor {
        ResolvedConstructor {
            declaring_type: name.to_string(),
            rust_name: "new".to_string(),
            constructed_type: JavaType::Named {
                name: name.to_string(),
                args: Vec::new(),
            },
            params: Vec::new(),
            arg_coercions: Vec::new(),
        }
    }

    fn facts_with_outer_this(inner: &str, outer: &str) -> FactSet {
        let mut facts = FactSet::default();
        facts.captures.owners.push(crate::facts::CaptureOwner {
            id: crate::facts::NodeId(0),
            kind: crate::facts::CaptureOwnerKind::InnerClass,
            name: Some(inner.to_string()),
            target_type: Some(JavaType::Named {
                name: inner.to_string(),
                args: Vec::new(),
            }),
            origin: crate::facts::CaptureOrigin::Type {
                type_name: inner.to_string(),
            },
            captures: vec![crate::facts::Capture {
                name: "__outer".to_string(),
                source: crate::facts::CaptureSource::OuterThis,
                ty: JavaType::Named {
                    name: outer.to_string(),
                    args: Vec::new(),
                },
                effectively_final: false,
                mutable_after_capture: true,
            }],
        });
        facts
    }

    #[test]
    fn same_outer_inner_constructor_owner_refuses_ambiguous_emitted_owner() {
        let support = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Inner")],
        }));
        let summary = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("b.Inner")],
        }));
        let facts = Box::leak(Box::new(facts_with_outer_this("a.Inner", "Outer")));
        let ctx = LowerCtx {
            program: &Program::default(),
            support_local_type_program: support,
            source_summary_type_program: summary,
            facts,
            ..lower_test_ctx()
        };

        assert!(same_outer_inner_constructor_owner("Inner", "Outer", ctx).is_none());
        assert_eq!(
            same_outer_inner_constructor_owner("AInner", "Outer", ctx).as_deref(),
            Some("a.Inner")
        );

        let duplicate_support = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Inner")],
        }));
        let duplicate_summary = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Inner")],
        }));
        let duplicate_facts = Box::leak(Box::new(facts_with_outer_this("a.Inner", "Outer")));
        let duplicate_ctx = LowerCtx {
            program: &Program::default(),
            support_local_type_program: duplicate_support,
            source_summary_type_program: duplicate_summary,
            facts: duplicate_facts,
            ..lower_test_ctx()
        };
        assert_eq!(
            same_outer_inner_constructor_owner("AInner", "Outer", duplicate_ctx).as_deref(),
            Some("a.Inner")
        );
    }

    #[test]
    fn array_element_default_lookup_refuses_cross_program_emitted_owner_collision() {
        let mut defaultable = empty_type_decl("a.B.C");
        defaultable.kind = TypeKind::Class;
        let mut non_defaultable = empty_type_decl("AB.C");
        non_defaultable.kind = TypeKind::Interface;
        let program = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![defaultable],
        }));
        let support = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![non_defaultable],
        }));
        let ctx = LowerCtx {
            program,
            support_local_type_program: support,
            ..lower_test_ctx()
        };
        assert_eq!(
            crate::java_naming::rust_name_for_java_named_type("a.B.C"),
            crate::java_naming::rust_name_for_java_named_type("AB.C")
        );
        let ambiguous_ty = JavaType::Named {
            name: "AB.C".to_string(),
            args: Vec::new(),
        };
        let exact_ty = JavaType::Named {
            name: "a.B.C".to_string(),
            args: Vec::new(),
        };
        let dimensions = vec![Expr::Literal(Literal::Int(2))];
        let ambiguous_plan = crate::array_plan::ArrayExprPlan::Creation {
            element_type: &ambiguous_ty,
            dimensions: &dimensions,
        };
        let exact_plan = crate::array_plan::ArrayExprPlan::Creation {
            element_type: &exact_ty,
            dimensions: &dimensions,
        };

        assert!(!array_element_type_has_default(&ambiguous_plan, ctx));
        assert!(array_element_type_has_default(&exact_plan, ctx));
    }

    fn assert_outer_this_handle_source_distinguishes_captured_inner_from_outer_receiver_gap() {
        let mut facts = facts_with_outer_this("Outer.A", "Outer");
        facts
            .captures
            .owners
            .extend(facts_with_outer_this("Outer.B", "Outer").captures.owners);

        assert_eq!(
            inner_constructor_outer_this_handle_source(
                &inner_constructor_target("Outer.B"),
                Some(&resolved_inner_constructor("Outer.B")),
                Some("Outer.A"),
                Some(ReceiverPlan::Shared),
                &facts,
            ),
            OuterThisHandleSource::CapturedInnerSelfOuterClone
        );

        assert_eq!(
            inner_constructor_outer_this_handle_source(
                &inner_constructor_target("Outer.B"),
                Some(&resolved_inner_constructor("Outer.B")),
                Some("Outer"),
                Some(ReceiverPlan::Shared),
                &facts,
            ),
            OuterThisHandleSource::CurrentOuterReceiverNeedsSharedHandle
        );

        assert_eq!(
            inner_constructor_outer_this_handle_source(
                &inner_constructor_target("Outer.B"),
                Some(&resolved_inner_constructor("Outer.B")),
                Some("Unrelated"),
                Some(ReceiverPlan::Shared),
                &facts,
            ),
            OuterThisHandleSource::Unavailable
        );
    }

    #[test]
    fn concrete_source_supertype_conversion_impl_is_loud_not_field_copy() {
        let support = Program {
            package: None,
            imports: Vec::new(),
            types: vec![TypeDecl {
                members: vec![instance_field(
                    "amount",
                    JavaType::Primitive(PrimitiveType::Int),
                )],
                ..empty_type_decl("Account")
            }],
        };
        let items = source_supertype_conversion_impls_for_pair(
            &TypeDecl {
                members: vec![
                    instance_field("amount", JavaType::Primitive(PrimitiveType::Int)),
                    instance_field("rate", JavaType::Primitive(PrimitiveType::Int)),
                ],
                ..empty_type_decl("Savings")
            },
            support.types.first().unwrap(),
            &support,
            &Program::default(),
            &RepresentationPlan::default(),
        )
        .expect("concrete source hierarchy conversion helper");
        let rendered = emit_file(&RustFile { items });

        assert!(rendered.contains("impl From<Savings> for Account"));
        assert!(
            rendered.contains(
                "panic!(\"unsupported Java class upcast: Savings to Account requires class hierarchy lowering\")"
            ),
            "{rendered}"
        );
        assert!(
            !rendered.contains("Account { amount: value.amount }"),
            "{rendered}"
        );
    }

